SELECT AVG(JPRAEMIE) AS AVG_PRIMAE
FROM T_VERTRAG
WHERE STAT_CD IN ('AKT', 'PRF');

SELECT SUM(T_SCH_ZLG.BETRAG) 
FROM T_SCHADEN 
WHERE T_SCH_ZLG.STAT_CD = 'OFF' AND BEZ_DAT IS NULL AND FAELLIG_DAT < '2026-06-30';

SELECT DISTINCT MARKE FROM T_OBJ_FZG
WHERE MARKE NOT IN (SELECT MARKE FROM T_OBJ_FZG)
GROUP BY MARKE;

SELECT COUNT(*) FROM T_AGENTUR WHERE AGT_ID IN (
    SELECT MA_ID_BER FROM T_MITARBEITER
    WHERE AGT_ID IN (
        SELECT AGT_ID_BER FROM T_SCHADEN WHERE STAT_CD IN ('OFF', 'PRF')
    )
)

SELECT T_AGENTUR.REGION
FROM T_AGENTUR
WHERE T_AGENTUR.REGION = 'Tessin';

SELECT T_OBJ_FZG.MARKE, T_OBJ_FZG.MODELL, T_OBJ_FZG.KATPREIS
FROM T_OBJ_FZG
WHERE T_OBJ_FZG.KATPREIS = (SELECT MAX(KATPREIS) FROM T_OBJ_FZG);

SELECT FZG_ID, MARKE, MODELL
FROM T_OBJ_FZG
WHERE KATPREIS = (SELECT MAX(KATPREIS) FROM T_OBJ_FZG);

SELECT SUM(T_SCH_ZLG.BETRAG) 
FROM T_SCH_ZLG 
WHERE T_SCH_ZLG.STAT_CD = 'AKT' AND BEZ_DAT IS NULL AND FAELLIG_DAT < '2026-06-30';

SELECT SUM(T_SCH_ZLG.BETRAG) FROM T_SCH_ADIC AS T_SCH_ADIC 
JOIN T_SCH_ZLG AS T_SCH_ZLG ON T_SCH_ADIC.SCH_ID = T_SCH_ZLG.SCH_ID 
WHERE T_SCH_ADIC.SCH_STAT_CD IN ('OFF', 'PRF') AND T_SCH_ADIC.BETRAG > 50000;

SELECT SUM(TS.BETRAG) AS Gesamtbetrag
FROM T_RECHNUNG TS
WHERE TS.FAQ_DAT < '2026-06-30' AND TS.STAT_CD IN ('OFF', 'PRF');

SELECT SUM(T_SCH_ZLG.BETRAG) 
FROM T_SCH_STAT_HIST 
WHERE T_SCH_STAT_HIST.STAT_CD = 'OFF' AND T_SCH_STAT_HIST.BETRAG > 50000;

SELECT SUM(CASE WHEN strftime('%Y', T_PARTNER.EROEFF_DAT) = '2025' THEN T_PARTNER.BETRUG_VERD_FLG ELSE 0 END) AS TOTAL_BEZAHLT
FROM T_PARTNER
WHERE T_PARTNER.REGION = 'Deutschschweiz' AND strftime('%Y', T_PARTNER.EROEFF_DAT) = '2025';

SELECT COUNT(T_SCHADEN.SCH_ID)
FROM T_SCHADEN
WHERE T_SCHADEN.BETRUG_VERD_FLG = 0;

SELECT AVG(T1.ERIEIG_DAT - T2.SCH_DAT) AS AVG_Durchschnitt
FROM T_SCHADEN AS T1
JOIN T_VERTRAG AS T2 ON T1.VTR_ID = T2.VTR_ID;

SELECT AVG(T_SCH_ZLG.BETRAG) AS GESAMTPROJEKT
FROM T_SCH_ZLG
WHERE T_SCH_ZLG.STAT_CD = 'ABG';

SELECT AVG(T_SCH_ZLG.BETRAG) FROM T_SCH_ZLG 
WHERE T_SCH_STAT_HIST.STAT_CD = 'AKT' AND T_SCH_ZLG.BETRAG > 50000
  AND T_SCH_ZLG.RG_DAT > '2026-06-30' AND T_SCH_ZLG.BETRAG IS NOT NULL AND T_SCH_ZLG.BETRAG != 0;

SELECT AVG(T_SCH_ZLG.BETRAG) AS GesamtGesamtzahlungProAbgeschlossenemKollisionsschaden
FROM T_SCH_ZLG
WHERE T_SCH_ZLG.STAT_CD IN ('OFF', 'PRF');

SELECT AVG(T_SCH_ZLG.BETRAG) as Gesamtzahlung
FROM T_SCH_STAT_HIST
WHERE T_SCH_STAT_HIST.SCH_ID IN ('OFF', 'PRF');

SELECT SUM(CASE WHEN T_VTR_ID IS NOT NULL THEN T_VTR_ID ELSE 0 END) AS SINISTRES_DECLARED
FROM T_VTRAG
WHERE TRUNC(T_EROEFF_DAT) = 2023 AND T_VTR_ID IS NOT NULL;

SELECT SUM(CASE WHEN T_PARTNER.STAT_CD = 'A' THEN 1 ELSE 0 END) AS sinistres_declaraes_2023
FROM T_PARTNER
WHERE STRFTIME('%Y', PTR_DAT) = '2023';

SELECT SUM(CASE WHEN T_Partner.STAT_CD = 'AKT' THEN 1 ELSE 0 END) AS COVERAGE_CASES
FROM T_PARTNER
WHERE T_Partner.REGION = 'Deutschschweiz' AND T_Partner.TK_CD IN ('TK', 'VK');

SELECT AVG(ERSCHL_CD) AS AVG_ERSCHL_CD
FROM T_PARTNER
WHERE STAT_CD = 'A';

SELECT AVG(T_PARTNER.KURZNAME) AS AVG_Kunden_Count
FROM T_PARTNER
WHERE T_PARTNER.STAT_CD = 'A';
